function search(nums, target) {
  // find rotation point, then ordinary binary search on the right segment
  const n = nums.length; let lo = 0, hi = n - 1;
  while (lo < hi) { const m = (lo + hi) >> 1; if (nums[m] > nums[hi]) lo = m + 1; else hi = m; }
  const k = lo;
  let a = 0, b = n - 1;
  while (a <= b) { const m = (a + b) >> 1, idx = (m + k) % n; if (nums[idx] === target) return idx; if (nums[idx] < target) a = m + 1; else b = m - 1; }
  return -1;
}
